import Testing
import Foundation
@testable import AlignmentCore

/// Parity with the Python reference on a fixture generated by scripts/generate_alignment_fixture.py.
struct ParityTests {
    struct Fixture: Decodable {
        struct Word: Decodable { let start, length: Int; let interval: [Int] }
        struct Row: Decodable {
            let id: Int; let proposal, estimate: [Int]?; let flags: [String]; let support, similarity: Double?
            let words, word_estimates: [Word]?; let onset_trim, offset_extension: Int?
        }
        struct Window: Decodable { let id, start, end, keep_start, keep_end: Int }
        struct Ratio: Decodable { let a, b: String; let ratio: Double }
        struct Head: Decodable { let level: [Double]; let reference: Double }
        let lyrics: String; let labels: [String]; let duration_us, frames: Int; let emissions, samples_head: String
        let tokens: [String]; let owners: [Int?]; let spans: [[Int]]?; let level: [Double]; let reference: Double
        let level_head: Head; let rows: [Row]; let windows: [Window]; let first_owned: [Int]; let ratios: [Ratio]
    }
    static let fixture: Fixture = {
        let url=Bundle.module.url(forResource:"parity",withExtension:"json",subdirectory:"Fixtures")!
        return try! JSONDecoder().decode(Fixture.self,from:Data(contentsOf:url))
    }()
    static func decode<T>(_ base64: String,_ type: T.Type) -> [T] {
        let data=Data(base64Encoded:base64)!
        return data.withUnsafeBytes { Array($0.bindMemory(to:T.self)) }
    }
    var f: Fixture { Self.fixture }
    var emissions: [[Double]] {
        let flat=Self.decode(f.emissions,Double.self),width=f.labels.count
        return (0..<f.frames).map { Array(flat[$0*width..<($0+1)*width]) }
    }
    var vocabulary: [String:Int] { Dictionary(uniqueKeysWithValues:f.labels.enumerated().map { ($1,$0) }) }

    @Test func targetsAndPathMatch() throws {
        let source=try LyricSource(Data(f.lyrics.utf8)),targets=try textTargets(source)
        #expect(targets.tokens==f.tokens && targets.owners==f.owners)
        let spans=try ctcPath(emissions,targets:targets.tokens.map { vocabulary[$0]! })
        #expect(spans==f.spans)
    }
    @Test func proposalsAndVocalRulesMatch() throws {
        let source=try LyricSource(Data(f.lyrics.utf8)),targets=try textTargets(source)
        let spans=try ctcPath(emissions,targets:targets.tokens.map { vocabulary[$0]! })
        var rows=try proposals(source,duration:f.duration_us,emissions:emissions,targets:targets,spans:spans,vocabulary:vocabulary)
        VocalRules.apply(&rows,level:f.level,reference:f.reference)
        #expect(rows.count==f.rows.count)
        for (row,expected) in zip(rows,f.rows) {
            #expect(row.proposal==expected.proposal && row.estimate==expected.estimate && row.flags==expected.flags)
            #expect(abs((row.support ?? 0)-(expected.support ?? 0))<1e-12 && abs((row.similarity ?? 0)-(expected.similarity ?? 0))<1e-12)
            #expect(row.words?.map { [$0.startUTF16,$0.lengthUTF16]+$0.interval }==expected.words?.map { [$0.start,$0.length]+$0.interval })
            #expect(row.wordEstimates?.map { [$0.startUTF16,$0.lengthUTF16]+$0.interval }==expected.word_estimates?.map { [$0.start,$0.length]+$0.interval })
            #expect(row.onsetTrim==expected.onset_trim && row.offsetExtension==expected.offset_extension)
        }
    }
    @Test func activityWindowsAndRatiosMatch() throws {
        let head=try VocalRules.activity(Self.decode(f.samples_head,Float.self))
        #expect(head.level.count==f.level_head.level.count)
        #expect(zip(head.level,f.level_head.level).allSatisfy { abs($0-$1)<1e-9 } && abs(head.reference-f.level_head.reference)<1e-9)
        let windows=try analysisWindows(samples:16000*70)
        #expect(windows.map { [$0.id,$0.startSample,$0.endSample,$0.keepStartSample,$0.keepEndSample] }==f.windows.map { [$0.id,$0.start,$0.end,$0.keep_start,$0.keep_end] })
        let w=windows[0]
        #expect(try ownedFrames(w,frameCount:(w.endSample-w.startSample-400)/320+1,expected:0)==f.first_owned)
        for r in f.ratios { #expect(abs(sequenceRatio(r.a,r.b)-r.ratio)<1e-15) }
    }
    @Test func sourceRejectsUnsupportedInput() {
        #expect(throws:AlignmentError.self) { try LyricSource(Data("a\n \nb".utf8)) }
        #expect(throws:AlignmentError.self) { try LyricSource(Data("1\n2\n3\n4\n5".utf8)) }
        #expect(throws:AlignmentError.self) { try textTargets(LyricSource(Data("日本語".utf8))) }
    }
}
